const body = $json.body ?? $json;
const periodStart = String(body.periodStart ?? '').trim();
const periodEnd = String(body.periodEnd ?? '').trim();
const forecastPeriods = Math.max(1, Math.min(12, Number(body.forecastPeriods ?? 3)));
const targetLeads = Number(body.targetLeads ?? 0);
if (!periodStart || !periodEnd) throw new Error('periodStart and periodEnd are required');
if (new Date(periodStart).getTime() > new Date(periodEnd).getTime()) throw new Error('periodStart must be before periodEnd');
if (!Number.isFinite(forecastPeriods) || forecastPeriods < 1) throw new Error('forecastPeriods must be at least 1');
if (!Number.isFinite(targetLeads) || targetLeads < 0) throw new Error('targetLeads must be non-negative');
return [{ json: { periodStart, periodEnd, forecastPeriods, targetLeads, requestedAt: new Date().toISOString() } }];

const ctx = $json.data ?? $json;
const records = Array.isArray(ctx.sources) ? ctx.sources : (Array.isArray(ctx.records) ? ctx.records : []);
const valid = records.filter(r => r && (r.source || r.leadSource || r.marketingChannel || r.channel));
if (!valid.length) throw new Error('No valid historical lead-source data available for the requested period');
return [{ json: { records: valid, periodStart: $('Normalize Forecast Request').first().json.periodStart, periodEnd: $('Normalize Forecast Request').first().json.periodEnd, forecastPeriods: $('Normalize Forecast Request').first().json.forecastPeriods, targetLeads: $('Normalize Forecast Request').first().json.targetLeads } }];

const records = $json.records;
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const grouped = new Map();
for (const r of records) {
  const source = String(r.source ?? r.leadSource ?? 'unknown');
  const channel = String(r.marketingChannel ?? r.channel ?? 'unknown');
  const key = source + '|' + channel;
  if (!grouped.has(key)) grouped.set(key, { source, marketingChannel: channel, periods: [], totalLeads: 0, totalQualifiedLeads: 0, totalContracts: 0, totalClosedDeals: 0 });
  const g = grouped.get(key);
  g.periods.push({ period: String(r.period ?? r.date ?? r.month ?? ''), leads: num(r.leads ?? r.leadCount), qualifiedLeads: num(r.qualifiedLeads ?? r.qualifiedLeadCount), contracts: num(r.contracts ?? r.contractCount), closedDeals: num(r.closedDeals ?? r.closedDealCount) });
  g.totalLeads += num(r.leads ?? r.leadCount);
  g.totalQualifiedLeads += num(r.qualifiedLeads ?? r.qualifiedLeadCount);
  g.totalContracts += num(r.contracts ?? r.contractCount);
  g.totalClosedDeals += num(r.closedDeals ?? r.closedDealCount);
}
const profiles = [...grouped.values()].map(g => {
  const n = g.periods.length;
  const recent = g.periods.slice(-3);
  const avgLeads = n ? g.totalLeads / n : 0;
  const recentAvg = recent.length ? recent.reduce((s,p) => s + p.leads, 0) / recent.length : avgLeads;
  const trend = avgLeads ? (recentAvg - avgLeads) / avgLeads : 0;
  const leadToQualifiedRate = g.totalLeads ? g.totalQualifiedLeads / g.totalLeads : 0;
  const leadToContractRate = g.totalLeads ? g.totalContracts / g.totalLeads : 0;
  const contractToCloseRate = g.totalContracts ? g.totalClosedDeals / g.totalContracts : 0;
  return { ...g, averageLeadsPerPeriod: avgLeads, recentAverageLeads: recentAvg, trendRate: trend, leadToQualifiedRate, leadToContractRate, contractToCloseRate };
});
const forecast = profiles.map(p => {
  const projectedPeriods = [];
  let base = p.recentAverageLeads || p.averageLeadsPerPeriod;
  for (let i = 1; i <= $json.forecastPeriods; i++) {
    const projectedLeads = Math.max(0, base * Math.pow(1 + Math.max(-0.5, Math.min(0.5, p.trendRate)), i));
    projectedPeriods.push({ periodIndex: i, projectedLeads: Number(projectedLeads.toFixed(2)), projectedQualifiedLeads: Number((projectedLeads * p.leadToQualifiedRate).toFixed(2)), projectedContracts: Number((projectedLeads * p.leadToContractRate).toFixed(2)), projectedClosedDeals: Number((projectedLeads * p.leadToContractRate * p.contractToCloseRate).toFixed(2)) });
  }
  return { source: p.source, marketingChannel: p.marketingChannel, historical: { averageLeadsPerPeriod: p.averageLeadsPerPeriod, recentAverageLeads: p.recentAverageLeads, trendRate: p.trendRate, leadToQualifiedRate: p.leadToQualifiedRate, leadToContractRate: p.leadToContractRate, contractToCloseRate: p.contractToCloseRate }, forecast: projectedPeriods };
});
const totals = forecast.reduce((a, f) => { for (const p of f.forecast) { a.projectedLeads += p.projectedLeads; a.projectedQualifiedLeads += p.projectedQualifiedLeads; a.projectedContracts += p.projectedContracts; a.projectedClosedDeals += p.projectedClosedDeals; } return a; }, { projectedLeads: 0, projectedQualifiedLeads: 0, projectedContracts: 0, projectedClosedDeals: 0 });
const targetGap = $json.targetLeads ? $json.targetLeads - totals.projectedLeads : null;
return [{ json: { periodStart: $json.periodStart, periodEnd: $json.periodEnd, forecastPeriods: $json.forecastPeriods, targetLeads: $json.targetLeads, sourceForecasts: forecast, totals: { projectedLeads: Number(totals.projectedLeads.toFixed(2)), projectedQualifiedLeads: Number(totals.projectedQualifiedLeads.toFixed(2)), projectedContracts: Number(totals.projectedContracts.toFixed(2)), projectedClosedDeals: Number(totals.projectedClosedDeals.toFixed(2)) }, targetGap: targetGap === null ? null : Number(targetGap.toFixed(2)), forecastMethod: 'recent-average-with-capped-trend-adjustment', generatedAt: new Date().toISOString() } }];
